Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_trim_left_no_leading_whitespace(void) {
    // Setup: buffer with no leading whitespace
    buffer_t *buf = helper_make_buffer_with_data("abc 123");

    // Precondition: buffer data points to start of string
    helper_assert_buffer_data_equals(buf, "abc 123");

    // Test: call buffer_trim_left (should not move data pointer)
    buffer_trim_left(buf);

    // Assertions: data pointer unchanged, contents unchanged
    helper_assert_buffer_data_equals(buf, "abc 123");

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_trim_left_no_leading_whitespace);
    return UNITY_END();
}

